import unittest


class TestAntiShuffle(unittest.TestCase):

    def test_basic_words(self):
        self.assertEqual(anti_shuffle('Hi'), 'Hi')

    def test_simple_sentence(self):
        self.assertEqual(anti_shuffle('hello world'), 'ehllo dlrorw'
