    def test_with_punctuation(self):
        self.assertEqual(anti_shuffle('Hello World!!!'), 'Hello !!!Wdlor')

    def test_already_sorted(self):
        self.assertEqual(anti_shuffle('abc def'), 'abc def')

    def test_single_word(self):
        self.assertEqual(anti_shuffle('banana'), 'aaabnn')

    def test_empty_string(self):
        self.assertEqual(anti_shuffle(''), '')

    def test_multiple_spaces_preserved(self):
        self.assertEqual(anti_shuffle('a  b'), 'a  b')
        self.assertEqual(anti_shuffle('   '), '   ')

    def test_mixed_case_sorts_by_ascii(self):
        # Uppercase letters sort before lowercase (ASCII order)
        self.assertEqual(anti_shuffle('bA'), 'Ab')
        self.assertEqual(anti_shuffle('aBc'), 'Bac')

    def test_numbers_and_symbols(self):
        self.assertEqual(anti_shuffle('321!@#'), '!@#123')

    def test_leading_trailing_spaces(self):
        self.assertEqual(anti_shuffle(' hi '), ' hi ')

    def test_result_is_rearrangement(self):
        original = 'python rocks'
        result = anti_shuffle(original)
        self.assertEqual(sorted(original.replace(' ', '')),
                         sorted(result.replace(' ', '')))
        self.assertEqual(len(original), len(result))

    def test_longer_sentence(self):
        self.assertEqual(
            anti_shuffle('the quick brown fox'),
            'eht cikqu bnorw fox'
        )


if __name__ == '__main__':
